324	    /**
325	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
326	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
327	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
328	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
329	     *
330	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
331	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
332	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
333	     * base region-and-hash code is returned unchanged.
334	     *
335	     * @param owner the owner being created, with its region-determining postcode and city populated
336	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
337	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
338	     */
339	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
340	        String region = ownerMapper.toRegion(owner);
341	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
342	        String baseCode = region + "-" + hash8;
343	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
344	            .map(Owner::getCustomerCode)
345	            .filter(java.util.Objects::nonNull)
346	            .collect(java.util.stream.Collectors.toSet());
347	        if (!existingCodes.contains(baseCode)) {
348	            return baseCode;
349	        }
350	        int n = 2;
351	        while (existingCodes.contains(baseCode + "-" + n)) {
352	            n++;
353	        }
354	        return baseCode + "-" + n;
355	    }
356	
357	    /**
358	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
359	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
360	     */
361	    private static String sha256Hex8(String value) {
362	        try {
363	            byte[] digest = MessageDigest.getInstance("SHA-256")
364	                .digest(value.getBytes(StandardCharsets.UTF_8));
365	            StringBuilder sb = new StringBuilder();
366	            for (byte b : digest) {
367	                sb.append(String.format("%02X", b));
368	            }
369	            return sb.substring(0, 8);
370	        }
371	        catch (NoSuchAlgorithmException e) {
372	            throw new IllegalStateException("SHA-256 not available", e);
373	        }
374	    }
