402	    /**
403	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
404	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
405	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
406	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
407	     * {@code "+61412345678"}.
408	     *
409	     * @param telephone the raw telephone value from the request
410	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
411	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
412	     */
413	    private static String normalizeTelephone(String telephone) {
414	        String e164 = toE164(telephone);
415	        if (e164 == null) {
416	            throw new InvalidFieldValueException("telephone",
417	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
418	        }
419	        return e164;
420	    }
421	
422	    /**
423	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
424	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
425	     * owners' stored numbers when detecting duplicates.
426	     */
427	    private static String toE164(String telephone) {
428	        if (telephone == null) {
429	            return null;
430	        }
431	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
432	        String digits;
433	        if (cleaned.startsWith("+")) {
434	            digits = cleaned.substring(1);
435	        } else {
436	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
437	            digits = "61" + national;
438	        }
439	        if (!digits.matches("[0-9]{8,15}")) {
440	            return null;
441	        }
442	        if (!hasValidNationalLength(digits)) {
443	            return null;
444	        }
445	        return "+" + digits;
446	    }
447	
448	    /**
449	     * Checks the national-number length against the country code for the country codes that pin one.
450	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
451	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
452	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
453	     */
454	    private static boolean hasValidNationalLength(String digits) {
455	        if (digits.startsWith("61")) {
456	            return digits.length() - 2 == 9;
457	        }
458	        if (digits.startsWith("1")) {
459	            return digits.length() - 1 == 10;
460	        }
461	        return true;
462	    }
