573	    /**
574	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
575	     * forward, just like a weekend, until it reaches a non-holiday business day.
576	     */
577	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
578	        LocalDate.of(2026, 1, 1),
579	        LocalDate.of(2026, 1, 26),
580	        LocalDate.of(2026, 4, 25),
581	        LocalDate.of(2026, 12, 25),
582	        LocalDate.of(2026, 12, 28));
583	
584	    /**
585	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
586	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
587	     * the effective registration date (whether supplied in the request or defaulted to the server date)
588	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
589	     * from the registration date uses the adjusted date.
590	     *
591	     * @param date the effective registration date (supplied or defaulted), never {@code null}
592	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
593	     */
594	    private static LocalDate toBusinessDay(LocalDate date) {
595	        LocalDate adjusted = date;
596	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
597	            adjusted = adjusted.plusDays(1);
598	        }
599	        return adjusted;
600	    }
601	
602	    /** Whether {@code date} falls on a Saturday or Sunday. */
603	    private static boolean isWeekend(LocalDate date) {
604	        DayOfWeek day = date.getDayOfWeek();
605	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
606	    }
