608	    /** Matches a well-formed postcode: exactly four decimal digits. */
609	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
610	
611	    /**
612	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
613	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
614	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
615	     * present here and accepts any well-formed postcode.
616	     */
617	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
618	        "NSW", new int[] {2000, 2099},
619	        "VIC", new int[] {3000, 3099},
620	        "QLD", new int[] {4000, 4099});
621	
622	    /**
623	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
624	     * optional, so the request contract stays backward-compatible). When present it must be exactly
625	     * four digits and, for a city whose region is known, fall within that region's inclusive range
626	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
627	     * postcode. A malformed or out-of-range value is rejected with a 400.
628	     *
629	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
630	     * @param city the owner's city, used to look up the region whose range constrains the postcode
631	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
632	     */
633	    private void validatePostcode(String postcode, String city) {
634	        if (postcode == null) {
635	            return;
636	        }
637	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
638	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
639	        }
640	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
641	        int[] range = REGION_POSTCODES.get(region);
642	        if (range == null) {
643	            return;
644	        }
645	        int value = Integer.parseInt(postcode);
646	        if (value < range[0] || value > range[1]) {
647	            throw new InvalidFieldValueException("postcode",
648	                "Postcode must be valid for the city's region " + region);
649	        }
650	    }
