652	    /**
653	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
654	     * date defaults to the server date). When present it must not be later than the current server
655	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
656	     *
657	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
658	     * @throws InvalidFieldValueException if the supplied date is later than the server date
659	     */
660	    private void validateRegistrationDate(LocalDate registrationDate) {
661	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
662	            throw new InvalidFieldValueException("registrationDate",
663	                "Registration date must not be later than the current date");
664	        }
665	    }
