22	
23	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
24	    @Mapping(target = "salutation", source = "owner", qualifiedByName = "toSalutation")
25	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
27	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
28	    @Mapping(target = "fiscalYear", source = "owner", qualifiedByName = "toFiscalYear")
29	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "toCheckDigit")
30	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
31	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
32	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
33	    @Mapping(target = "timezone", source = "owner", qualifiedByName = "toTimezone")
34	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
35	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
36	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
37	    @Mapping(target = "selfLink", source = "owner", qualifiedByName = "toSelfLink")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's {@code selfLink}: its canonical relative URL, {@code '/api/owners/'}
42	     * followed by the owner's id. Returns {@code null} when the owner has no id yet.
43	     */
44	    @Named("toSelfLink")
45	    default String toSelfLink(Owner owner) {
46	        if (owner == null || owner.getId() == null) {
47	            return null;
48	        }
49	        return "/api/owners/" + owner.getId();
50	    }
51	
52	    /**
53	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
54	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
55	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
56	     * {@code null} when either the birth date or the registration date is absent.
57	     */
58	    @Named("toAgeBand")
59	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
60	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
64	        if (age < 18) {
65	            return OwnerDto.AgeBandEnum.MINOR;
66	        }
67	        if (age < 65) {
68	            return OwnerDto.AgeBandEnum.ADULT;
69	        }
70	        return OwnerDto.AgeBandEnum.SENIOR;
71	    }
72	
73	    /**
74	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
75	     * the former separate telephone, email and household checks. It is the owner's normalized
76	     * telephone, its email (lower-cased and trimmed, or the empty string when absent) and its
77	     * household identifier (or the empty string when absent), joined in that order by {@code '|'}.
78	     * Because the telephone is part of the key, two members of the same household with different
79	     * telephones have different identity keys; only an exact full-key match is a duplicate.
80	     */
81	    @Named("toIdentityKey")
82	    default String toIdentityKey(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
87	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
88	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
89	        return telephone + "|" + email + "|" + householdId;
90	    }
91	
92	    /**
93	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
94	     * email, otherwise {@code 'PHONE'}.
95	     */
96	    @Named("toContactPreference")
97	    default String toContactPreference(Owner owner) {
98	        if (owner == null) {
99	            return null;
100	        }
101	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
102	        return hasEmail ? "EMAIL" : "PHONE";
103	    }
104	
105	    /**
106	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
107	     */
108	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
109	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
110	
111	    /**
112	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
113	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
114	     */
115	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
116	        "NSW", "Australia/Sydney",
117	        "VIC", "Australia/Melbourne",
118	        "QLD", "Australia/Brisbane");
119	
120	    /**
121	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
122	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
123	     * owner's locality from its postcode in preference to its city.
124	     */
125	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
126	        "NSW", new int[] {2000, 2099},
127	        "VIC", new int[] {3000, 3099},
128	        "QLD", new int[] {4000, 4099});
129	
130	    /**
131	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
132	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
133	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
134	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
135	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
136	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
137	     * the same region for known cities but disambiguates cities that share a name.
138	     */
139	    default String toRegion(Owner owner) {
140	        if (owner == null) {
141	            return null;
142	        }
143	        String regionByPostcode = regionForPostcode(owner.getPostcode());
144	        if (regionByPostcode != null) {
145	            return regionByPostcode;
146	        }
147	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
148	    }
149	
150	    /**
151	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
152	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
153	     * the customer code's identity rather than being computed independently. When the customer code
154	     * is absent the region is derived directly from the owner's postcode and city via
155	     * {@link #toRegion(Owner)}.
156	     */
157	    @Named("toLocality")
158	    default String toLocality(Owner owner) {
159	        if (owner == null) {
160	            return null;
161	        }
162	        String customerCode = owner.getCustomerCode();
163	        if (customerCode != null) {
164	            int dash = customerCode.indexOf('-');
165	            if (dash >= 0) {
166	                return customerCode.substring(0, dash);
167	            }
168	        }
169	        return toRegion(owner);
170	    }
171	
172	    /**
173	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
174	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
175	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
176	     * owner's region is not one of the tabled regions.
177	     */
178	    @Named("toTimezone")
179	    default String toTimezone(Owner owner) {
180	        if (owner == null) {
181	            return null;
182	        }
183	        return REGION_TIMEZONE.get(toLocality(owner));
184	    }
185	
186	    /**
187	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
188	     * {@code null} when the postcode is absent, malformed, or in no known range.
189	     */
190	    private static String regionForPostcode(String postcode) {
191	        if (postcode == null || !postcode.matches("\\d{4}")) {
192	            return null;
193	        }
194	        int value = Integer.parseInt(postcode);
195	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
196	            int[] range = entry.getValue();
197	            if (value >= range[0] && value <= range[1]) {
198	                return entry.getKey();
199	            }
200	        }
201	        return null;
202	    }
203	
204	    /**
205	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
206	     */
207	    @Named("toDisplayName")
208	    default String toDisplayName(Owner owner) {
209	        if (owner == null) {
210	            return null;
211	        }
212	        return owner.getLastName() + ", " + owner.getFirstName();
213	    }
214	
215	    /**
216	     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
217	     * by a single space when a title is present, or just the {@code lastName} when no title is
218	     * supplied (absent or blank).
219	     */
220	    @Named("toSalutation")
221	    default String toSalutation(Owner owner) {
222	        if (owner == null) {
223	            return null;
224	        }
225	        String title = owner.getTitle();
226	        if (title == null || title.isBlank()) {
227	            return owner.getLastName();
228	        }
229	        return title + " " + owner.getLastName();
230	    }
231	
232	    /**
233	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
234	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
235	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
236	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
237	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
238	     * untouched.
239	     */
240	    @Named("toTelephoneDisplay")
241	    default String toTelephoneDisplay(Owner owner) {
242	        if (owner == null) {
243	            return null;
244	        }
245	        String telephone = owner.getTelephone();
246	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
247	            return telephone;
248	        }
249	        String digits = telephone.substring(1);
250	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
251	        String countryCode = digits.substring(0, countryCodeLength);
252	        String national = digits.substring(countryCodeLength);
253	        StringBuilder sb = new StringBuilder("+").append(countryCode);
254	        for (int i = 0; i < national.length(); i++) {
255	            if (i % 3 == 0) {
256	                sb.append(' ');
257	            }
258	            sb.append(national.charAt(i));
259	        }
260	        return sb.toString();
261	    }
262	
263	    /**
264	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
265	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
266	     */
267	    @Named("toInitials")
268	    default String toInitials(Owner owner) {
269	        if (owner == null) {
270	            return null;
271	        }
272	        return initial(owner.getFirstName()) + initial(owner.getLastName());
273	    }
274	
275	    /**
276	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
277	     * the last two digits of the fiscal year of the {@code registrationDate}, e.g.
278	     * {@code 'NSW-1A2B3C4D-M26'}. The fiscal year starts on 1 July and is identified by the calendar
279	     * year in which it ends. Returns {@code null} when either the customer code or the registration
280	     * date is absent.
281	     */
282	    @Named("toMembershipNumber")
283	    default String toMembershipNumber(Owner owner) {
284	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
285	            return null;
286	        }
287	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear(owner.getRegistrationDate()) % 100);
288	    }
289	
290	    /**
291	     * Derives the owner's {@code fiscalYear} from its {@code registrationDate}, formatted
292	     * {@code 'FY<YY>'} where {@code YY} is the last two digits of the fiscal year, e.g. {@code 'FY26'}.
293	     * The fiscal year starts on 1 July and is identified by the calendar year in which it ends: a date
294	     * from 1 July onwards belongs to the fiscal year ending in the following calendar year, and a date
295	     * before 1 July to the fiscal year ending in the same calendar year. Returns {@code null} when the
296	     * registration date is absent.
297	     */
298	    @Named("toFiscalYear")
299	    default String toFiscalYear(Owner owner) {
300	        if (owner == null || owner.getRegistrationDate() == null) {
301	            return null;
302	        }
303	        return String.format("FY%02d", fiscalYear(owner.getRegistrationDate()) % 100);
304	    }
305	
306	    /**
307	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
308	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
309	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
310	     * in its own calendar year.
311	     *
312	     * @param date the date whose fiscal year is computed, never {@code null}
313	     * @return the calendar year in which the date's fiscal year ends
314	     */
315	    static int fiscalYear(LocalDate date) {
316	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
317	    }
318	
319	    /**
320	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
321	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
322	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
323	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
324	     * This qualified mapping cannot observe the owner's household size (which requires counting other
325	     * owners), so it computes the points as if the owner were the only member of its household; the
326	     * controller recomputes the points with the real household size via
327	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
328	     */
329	    @Named("toMembershipPoints")
330	    default Integer toMembershipPoints(Owner owner) {
331	        if (owner == null) {
332	            return null;
333	        }
334	        return membershipPointsFor(owner, 1);
335	    }
336	
337	    /**
338	     * Returns the owner's numeric membership level, derived from its membership points: level
339	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
340	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
341	     * is not observable here and is treated as a single member.
342	     */
343	    @Named("toMembershipLevel")
344	    default Integer toMembershipLevel(Owner owner) {
345	        if (owner == null) {
346	            return null;
347	        }
348	        return membershipLevelFor(membershipPointsFor(owner, 1));
349	    }
350	
351	    /**
352	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
353	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
354	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
355	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
356	     * the {@code registrationDate} and today.
357	     *
358	     * @param owner the owner whose points are computed, never {@code null}
359	     * @param householdSize the number of owners sharing the owner's household
360	     * @return the owner's membership points
361	     */
362	    static int membershipPointsFor(Owner owner, int householdSize) {
363	        int points = 0;
364	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
365	        if (hasEmail) {
366	            points += 2;
367	        }
368	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
369	        if (noNamesakes) {
370	            points += 1;
371	        }
372	        if (householdSize >= 3) {
373	            points += 2;
374	        }
375	        boolean tenured = owner.getRegistrationDate() != null
376	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
377	        if (tenured) {
378	            points += 3;
379	        }
380	        return points;
381	    }
382	
383	    /**
384	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
385	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
386	     *
387	     * @param points the owner's membership points
388	     * @return the corresponding membership level (1-4)
389	     */
390	    static int membershipLevelFor(int points) {
391	        if (points <= 1) {
392	            return 1;
393	        }
394	        if (points <= 3) {
395	            return 2;
396	        }
397	        if (points <= 5) {
398	            return 3;
399	        }
400	        return 4;
401	    }
402	
403	    /**
404	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
405	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
406	     * absent.
407	     */
408	    @Named("toCheckDigit")
409	    default Integer toCheckDigit(Owner owner) {
410	        if (owner == null || owner.getCustomerCode() == null) {
411	            return null;
412	        }
413	        int sum = 0;
414	        boolean dbl = true;
415	        String code = owner.getCustomerCode();
416	        for (int i = code.length() - 1; i >= 0; i--) {
417	            char c = code.charAt(i);
418	            if (c < '0' || c > '9') {
419	                continue;
420	            }
421	            int d = c - '0';
422	            if (dbl) {
423	                d *= 2;
424	                if (d > 9) {
425	                    d -= 9;
426	                }
427	            }
428	            sum += d;
429	            dbl = !dbl;
430	        }
431	        return (10 - (sum % 10)) % 10;
432	    }
433	
434	    private static String initial(String name) {
435	        if (name == null || name.isEmpty()) {
436	            return "";
437	        }
438	        return Character.toUpperCase(name.charAt(0)) + ".";
439	    }
440	
441	    Owner toOwner(OwnerDto ownerDto);
442	
443	    @Mapping(target = "id", ignore = true)
444	    @Mapping(target = "pets", ignore = true)
445	    Owner toOwner(OwnerFieldsDto ownerDto);
446	
447	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
448	
449	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
450	
451	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
452	        OwnerPageDto ownerPageDto = new OwnerPageDto();
453	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
454	        ownerPageDto.setPage(ownerPage.getNumber());
455	        ownerPageDto.setSize(ownerPage.getSize());
456	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
457	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
458	        return ownerPageDto;
459	    }
460	}
